// Pick exactly ONE product per day so downstream nodes run only once per day
const allItems = $input.all();
if (!allItems || allItems.length === 0) {
  throw new Error('No products found in Google Sheet "Products"! Please add rows first.');
}

// Rotate through products based on day of year (1-365)
const today = new Date();
const start = new Date(today.getFullYear(), 0, 0);
const dayOfYear = Math.floor((today - start) / 86400000);
const index = dayOfYear % allItems.length;

const row = allItems[index].json;

// Safe field extraction supporting multiple column naming conventions
const productName = row['Product Name'] || row['name'] || row['Name'] || row['product_name'] || 'Califnco AquaPure RO Purifier';
const productDescription = row['Description'] || row['description'] || row['desc'] || 'Advanced multi-stage RO water purification system with mineral booster';
const productPrice = String(row['Price'] || row['price'] || row['MRP'] || '14999');
const category = row['Category'] || row['category'] || 'RO Purifier';

return [{
  json: {
    productName,
    productDescription,
    productPrice,
    category,
    dayIndex: index,
    totalProducts: allItems.length
  }
}];

