// Generate Ultra-Premium Commercial Offer Banner using Hugging Face FLUX Space + Upload to ImgBB
const product = $('Select Product for Today').first().json;
const hfToken = $vars.HF_API_TOKEN;
const imgbbKey = $vars.IMGBB_API_KEY;

const name = product.productName || 'Califnco Smart RO Water Purifier';
const price = product.productPrice || '14999';
const category = (product.category || 'RO Purifier').toLowerCase();

let productVisual = 'luxury Apple-style wall-mounted Califnco smart RO water purifier with sleek digital touch display, glowing neon blue LED indicator, brushed aluminum accents, transparent pure mineral water chamber';
if (category.includes('filter') || category.includes('membrane') || category.includes('carbon') || category.includes('sediment')) {
  productVisual = 'high-performance genuine Califnco multi-layer RO filter cartridge with glowing crystal blue water flow inside a transparent core';
} else if (category.includes('pump') || category.includes('booster')) {
  productVisual = 'heavy-duty commercial Califnco RO booster pump with precision copper motor and pressurized pure water stream';
} else if (category.includes('dispenser')) {
  productVisual = 'ultra-premium matte black and brushed stainless steel Califnco hot and cold water dispenser with a crystal clear glass filling with pure water';
} else if (category.includes('spare') || category.includes('part')) {
  productVisual = 'precision-engineered Califnco genuine spare parts with digital TDS tester in high-tech presentation';
}

const promptText = `Ultra-luxury commercial product advertisement poster for "${name}", featuring ${productVisual} front and center on a polished white Italian marble countertop in a modern Chennai designer luxury penthouse kitchen. Elegant glowing typography badge: "CALIFNCO SPECIAL OFFER ₹${price}", "FREE INSTALLATION & TDS TEST", frozen high-speed crystal-clear splashing pure water droplets curling around the product, dramatic cinematic studio lighting with soft cyan backlighting, subtle gold highlights, 3D luxury commercial graphic design, 8k resolution, hyperrealistic, award-winning social media ad banner`;

// 1. Fetch Hugging Face Space JWT
const jwt = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://huggingface.co/api/spaces/black-forest-labs/FLUX.1-schnell/jwt',
  headers: { 'Authorization': 'Bearer ' + hfToken }
});
const cleanJwt = String(jwt).replace(/"/g, '').trim();

// 2. Queue inference on FLUX Space
const sessionHash = Math.random().toString(36).substring(2);
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://black-forest-labs-flux-1-schnell.hf.space/gradio_api/queue/join',
  headers: {
    'Authorization': 'Bearer ' + hfToken,
    'Content-Type': 'application/json'
  },
  body: {
    data: [promptText, 0, true, 1024, 1024, 4],
    event_data: null,
    fn_index: 2,
    trigger_id: null,
    session_hash: sessionHash
  },
  json: true
});

// 3. Listen to SSE for generated image
const text = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://black-forest-labs-flux-1-schnell.hf.space/gradio_api/queue/data',
  qs: { session_hash: sessionHash, __sign: cleanJwt },
  headers: {
    'Authorization': 'Bearer ' + hfToken,
    'Accept': 'text/event-stream'
  }
});

const match = String(text).match(/https:\/\/[^\s"']+\/image\.webp[^\s"']*/);
if (!match) {
  throw new Error('Hugging Face FLUX generation failed: ' + String(text).slice(-200));
}

const hfImageUrl = match[0];

// 4. Download generated image buffer
const imgBuf = await this.helpers.httpRequest({
  method: 'GET',
  url: hfImageUrl,
  encoding: 'arraybuffer'
});

const base64 = Buffer.from(imgBuf).toString('base64');
const postData = 'key=' + encodeURIComponent(imgbbKey) + '&image=' + encodeURIComponent(base64) + '&name=califnco_flux_' + Date.now();

// 5. Upload to ImgBB for direct Instagram CDN URL
const imgbbRes = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.imgbb.com/1/upload',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: postData,
  json: true
});

const publicUrl = imgbbRes.data.url;

return [{
  json: {
    ...product,
    imageUrl: publicUrl
  }
}];
